<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">我的报价</h1><div v-for="item in items" :key="item.id" class="m-card"><p class="font-semibold text-slate-800">{{ money(item.price_minor,item.currency) }}</p><p class="text-xs text-slate-400">{{ item.status }}</p><button v-if="item.status==='submitted'" class="mt-3 text-xs font-semibold text-red-500" @click="withdraw(item.id)">Withdraw</button></div></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const api=useCommerce();const items=ref<any[]>([]);const money=(v:number,c:string)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(v/100);async function load(){items.value=(await api.listSupplierOffers()).items}async function withdraw(id:string){await api.withdrawSupplierOffer(id);await load()}onMounted(load)</script>
